  1	import "./styles.css";
  2	
  3	import { invoke } from "@tauri-apps/api/core";
  4	import { emit, emitTo, listen } from "@tauri-apps/api/event";
  5	import { getVersion } from "@tauri-apps/api/app";
  6	import { exit } from "@tauri-apps/plugin-process";
  7	import { enable, disable, isEnabled } from "@tauri-apps/plugin-autostart";
  8	import { loadCatalog, savedSlug, getLibrary, addToLibrary, removeFromLibrary, petDisplayName, type Pet as CatalogPet, type LibPet } from "./catalog";
  9	import { t, getLang, setLang, type Lang } from "./i18n";
 10	import { uiIcon } from "./icons";
 11	
 12	import { slice, type Rect } from "./pet";
 13	import { Pet as AnimatedPet } from "./pet";
 14	
 15	import * as care from "./care";
 16	import {
 17	  createPetInstance,
 18	  initializePetStore,
 19	  newPetInstanceId,
 20	  removePetInstance,
 21	  savePetStore,
 22	  selectPetInstance,
 23	  selectedPetInstance,
 24	  updatePetInstance,
 25	  type PetInstance,
 26	  type PetStore,
 27	} from "./pets";
 28	import { DEFAULT_WANDER_PAUSE_MAX_MS, DEFAULT_WANDER_PAUSE_MIN_MS } from "./roam/pause";
 29	import {
 30	  QUICK_BUBBLE_DURATION_KEY,
 31	  normalizeQuickBubbleDurationSeconds,
 32	} from "./quick-bubble";
 33	
 34	function legacyPet() {
 35	  const slug = savedSlug();
 36	  return slug ? { slug, name: petDisplayName(slug) } : null;
 37	}
 38	
 39	function currentPetStore(): PetStore {
 40	  return initializePetStore(legacyPet());
 41	}
 42	
 43	function currentPetInstance(): PetInstance | null {
 44	  return selectedPetInstance(currentPetStore());
 45	}
 46	
 47	function syncDesktopPetWindows(store: PetStore): Promise<void> {
 48	  return invoke("sync_desktop_pet_windows", {
 49	    pets: store.instances.map(({ id, visible }) => ({ id, visible })),
 50	  });
 51	}
 52	
 53	type PersistDesktopPetsOptions = {
 54	  syncWindows?: boolean;
 55	  instanceId?: string;
 56	};
 57	
 58	function persistDesktopPets(store: PetStore, options: PersistDesktopPetsOptions = {}): void {
 59	  const { syncWindows = true, instanceId } = options;
 60	  savePetStore(store);
 61	  if (syncWindows) void syncDesktopPetWindows(store).catch((error) => alert(String(error)));
 62	  if (instanceId) {
 63	    void emitTo(`pet-${instanceId}`, "pet-instance-changed", { instanceId }).catch(() => {});
 64	  } else {
 65	    void emit("pets-changed");
 66	  }
 67	}
 68	
 69	function instanceFromLibrary(pet: LibPet): PetInstance {
 70	  return {
 71	    id: newPetInstanceId(),
 72	    name: pet.name,
 73	    spriteSlug: pet.slug,
 74	    visible: true,
 75	    size: 100,
 76	    roamEnabled: true,
 77	    roamMode: "wander",
 78	    roamSpeed: 5,
 79	    wanderPauseMinMs: DEFAULT_WANDER_PAUSE_MIN_MS,
 80	    wanderPauseMaxMs: DEFAULT_WANDER_PAUSE_MAX_MS,
 81	    reactsToActivity: false,
 82	  };
 83	}
 84	
 85	// ------------------------------------------------------------- segmented ----
 86	// macOS-style segmented controls: <span class="seg" data-key data-default>.
 87	function initSegs() {
 88	  document.querySelectorAll<HTMLElement>(".seg[data-key]").forEach((seg) => {
 89	    const key = seg.dataset.key!;
 90	    const current = localStorage.getItem(key) || seg.dataset.default || "";
 91	    const btns = seg.querySelectorAll<HTMLButtonElement>("button");
 92	    btns.forEach((b) => {
 93	      b.classList.toggle("sel", b.dataset.v === current);
 94	      b.onclick = () => {
 95	        localStorage.setItem(key, b.dataset.v!);
 96	        btns.forEach((x) => x.classList.toggle("sel", x === b));
 97	        emit("bubble-changed", null);
 98	        document.dispatchEvent(new CustomEvent("seg-changed", { detail: key }));
 99	      };
100	    });
101	  });
102	}
103	
104	// ------------------------------------------------------------------ tabs ----
105	function initTabs() {
106	  const tabs = document.querySelectorAll<HTMLButtonElement>(".tabbar .tab");
107	  const setWorkspaceMode = (tab: string | undefined) => {
108	    document.body.classList.toggle("image-workspace-active", tab === "image");
109	  };
110	  tabs.forEach((b) => {
111	    b.onclick = () => {
112	      tabs.forEach((x) => x.classList.toggle("sel", x === b));
113	      document.querySelectorAll<HTMLElement>(".page").forEach((p) => {
114	        p.classList.toggle("sel", p.dataset.page === b.dataset.tab);
115	      });
116	      setWorkspaceMode(b.dataset.tab);
117	      if (b.dataset.tab === "care") renderCare();
118	      if (b.dataset.tab === "pet") document.dispatchEvent(new CustomEvent("ap-pet-tab-shown"));
119	    };
120	  });
121	  setWorkspaceMode(document.querySelector<HTMLButtonElement>(".tabbar .tab.sel")?.dataset.tab);
122	}
123	
124	// ------------------------------------------------------------------ care ----
125	function fmtNum(n: number): string {
126	  n = Number(n) || 0;
127	  if (n >= 1e9) return (n / 1e9).toFixed(1).replace(/\.0$/, "") + "B";
128	  if (n >= 1e6) return (n / 1e6).toFixed(1).replace(/\.0$/, "") + "M";
129	  if (n >= 1e3) return (n / 1e3).toFixed(1).replace(/\.0$/, "") + "K";
130	  return String(n);
131	}
132	function currentPetName(): string {
133	  return currentPetInstance()?.name || t("Your pet");
134	}
135	function renderCare() {
136	  const instance = currentPetInstance();
137	  const empty = document.getElementById("care-empty");
138	  const hud = document.querySelector(".care-hud") as HTMLElement | null;
139	  if (!instance) {
140	    if (empty) empty.style.display = "";
141	    // Keep the left panel visible but show a placeholder state
142	    const name = document.getElementById("care-name");
143	    if (name) name.textContent = t("No pet yet");
144	    const stage = document.getElementById("care-stagename");
145	    if (stage) stage.textContent = "";
146	    const hunger = document.getElementById("care-hunger");
147	    if (hunger) hunger.textContent = "";
148	    const level = document.getElementById("care-level");
149	    if (level) level.textContent = "";
150	    const xp = document.getElementById("care-xp");
151	    if (xp) xp.textContent = "";
152	    const tonext = document.getElementById("care-tonext");
153	    if (tonext) tonext.textContent = "";
154	    const fill = document.getElementById("care-xpfill");
155	    if (fill) fill.style.width = "0%";
156	    return;
157	  }
158	  if (empty) empty.style.display = "none";
159	  if (hud) hud.style.display = "";
160	  const s = care.stateFor(instance.id);
161	  const internal = care.levelForXP(s.xp);
162	  const setTxt = (id: string, v: string) => { const el = document.getElementById(id); if (el) el.textContent = v; };
163	  setTxt("care-name", instance.name);
164	  setTxt("care-level", `${t("Lv")} ${care.displayLevel(s.xp)}`);
165	  setTxt("care-stagename", t(care.stageName(internal)));
166	  setTxt("care-hunger", t(care.hunger(s)));
167	  const fill = document.getElementById("care-xpfill");
168	  if (fill) fill.style.width = `${Math.round(care.levelProgress(s.xp) * 100)}%`;
169	  setTxt("care-xp", `${s.xp} XP`);
170	  const toNext = Math.max(0, care.xpToReach(care.levelForXP(s.xp) + 1) - s.xp);
171	  setTxt("care-tonext", toNext > 0 ? `≈ ${fmtNum(toNext)} ${t("XP to next level")}` : "");
172	  // achievements
173	  const unlocked = new Set(s.unlockedAchievements || []);
174	  setTxt("care-achcount", `${unlocked.size} / ${care.ACHIEVEMENTS.length}`);
175	  const badges = document.getElementById("care-badges");
176	  if (badges) badges.innerHTML = care.ACHIEVEMENTS
177	    .map((a) => `<span class="care-badge${unlocked.has(a) ? " on" : ""}" title="${t(care.ACH_NAME[a])}">${uiIcon(care.ACH_ICON[a])}</span>`)
178	    .join("");
179	  setTxt("care-today", fmtNum(s.tokensToday));
180	  setTxt("care-today-sub", `${s.mealsToday} ${t("sessions")}`);
181	  setTxt("care-streak", String(s.streakDays));
182	  setTxt("care-lifetime", fmtNum(s.xp));
183	  setTxt("care-sessions", String(s.totalMeals));
184	  const days = care.recentDays(s, 7);
185	  const max = Math.max(1, ...days.map((d) => d.tokens));
186	  setTxt("care-burntotal", fmtNum(days.reduce((a, d) => a + d.tokens, 0)));
187	  const chart = document.getElementById("care-chart");
188	  if (chart) chart.innerHTML = days
189	    .map((d) => `<div class="cbar-wrap" title="${fmtNum(d.tokens)}"><div class="cbar" style="height:${Math.max(3, Math.round((d.tokens / max) * 100))}%"></div><div class="cbar-lbl">${d.label}</div></div>`)
190	    .join("");
191	}
192	// Click the pet's name to rename it; Enter or blur saves (empty resets to the
193	// default). The custom name flows to the HUD, menubar, and web leaderboard.
194	function setupRename() {
195	  const nameEl = document.getElementById("care-name");
196	  const input = document.getElementById("care-rename") as HTMLInputElement | null;
197	  if (!nameEl || !input) return;
198	  const startEdit = () => {
199	    if (!currentPetInstance()) return;
200	    input.value = currentPetName();
201	    nameEl.style.display = "none";
202	    input.style.display = "";
203	    input.focus();
204	    input.select();
205	  };
206	  const commit = () => {
207	    const instance = currentPetInstance();
208	    if (instance) {
209	      persistDesktopPets(
210	        updatePetInstance(currentPetStore(), instance.id, { name: input.value.trim() || instance.spriteSlug }),
211	        { syncWindows: false, instanceId: instance.id },
212	      );
213	    }
214	    input.style.display = "none";
215	    nameEl.style.display = "";
216	    renderCare();
217	    emit("care-updated");
218	  };
219	  nameEl.addEventListener("click", startEdit);
220	  input.addEventListener("blur", commit);
221	  input.addEventListener("keydown", (e) => {
222	    if (e.key === "Enter") { e.preventDefault(); input.blur(); }
223	    else if (e.key === "Escape") { input.value = currentPetName(); input.blur(); }
224	  });
225	}
226	setupRename();
227	
228	// Manual feeding (pure-pet interaction: the pet eats a snack on demand).
229	const feedBtn = document.getElementById("care-feed-btn") as HTMLButtonElement | null;
230	if (feedBtn) {
231	  feedBtn.onclick = () => {
232	    const instance = currentPetInstance();
233	    if (!instance) return;
234	    const leveled = care.feed(instance.id, (state) => care.recordMeal(state));
235	    emit("care-updated", { instanceId: instance.id });
236	    if (leveled) emit("quick-bubble", { text: `${t("Level up")}! ${t("Lv")} ${care.displayLevel(care.stateFor(instance.id).xp)}` });
237	    renderCare();
238	  };
239	}
240	
241	// Refresh when the pet window feeds the pet, and periodically for the hunger clock.
242	listen("care-updated", () => { renderCare(); });
243	// The left pet panel is always visible — keep its state fresh even when
244	// the Care tab itself isn't selected.
245	setInterval(() => { renderCare(); }, 30_000);
246	
247	// ------------------------------------------------------------------ pet ----
248	// macOS model: the pager shows your INSTALLED pets (library); the full catalog
249	// lives in the Browse dialog where "Get" adds a pet to the library.
250	const current = document.getElementById("pet-current") as HTMLDivElement | null;
251	const search = document.getElementById("pet-search") as HTMLInputElement;
252	const results = document.getElementById("pet-results") as HTMLDivElement;
253	
254	// ---- living pet: the left pet-panel canvas animates the current pet with
255	// the same engine as the desktop window (Pet from ./pet). Identity/XP/hunger
256	// text is rendered by renderCare() into the care-* hooks in the panel.
257	let stagePet: AnimatedPet | null = null;
258	
259	function initLivingPets() {
260	  const c2 = document.getElementById("hero-live") as HTMLCanvasElement | null;
261	  if (c2) stagePet = new AnimatedPet(c2);
262	  let loadedUrl: string | null = null;
263	  const loadPet = (url: string | null) => {
264	    if (!url || url === loadedUrl) return;
265	    loadedUrl = url;
266	    stagePet?.load(url);
267	  };
268	  return { loadPet };
269	}
270	
271	const livingPets = initLivingPets();
272	
273	let catalog: CatalogPet[] = [];
274	
275	function selectedPet(): LibPet | undefined {
276	  const instance = currentPetInstance();
277	  return instance ? getLibrary().find((pet) => pet.slug === instance.spriteSlug) : undefined;
278	}
279	
280	let refreshDesktopPets: () => void = () => {};

