 916	
 917	  const boundClip = (m: string) => {
 918	    const v = parseInt(localStorage.getItem(`ap_bind_${m}`) ?? "", 10);
 919	    return Number.isFinite(v) && v >= 0 ? Math.min(v, Math.max(0, clips.length - 1)) : Math.min(MOOD_DEFAULT_ROW[m] ?? 0, Math.max(0, clips.length - 1));
 920	  };
 921	
 922	  const readIdleClips = (): number[] => {
 923	    try {
 924	      const v = JSON.parse(localStorage.getItem(IDLE_CLIPS_KEY) || "[]");
 925	      if (Array.isArray(v) && v.length) return v.filter((x) => Number.isFinite(x) && x >= 0).map((x) => Number(x));
 926	    } catch {}
