1106	let settingsAudioCtx: AudioContext | null = null;
1107	function playSound(ev: "done" | "waiting") {
1108	  const data = localStorage.getItem(`ap_sound_${ev}_data`);
1109	  if (data) {
1110	    try { void new Audio(data).play(); return; } catch {}
1111	  }
1112	  try {
1113	    settingsAudioCtx = settingsAudioCtx || new AudioContext();
1114	    const o = settingsAudioCtx.createOscillator();
1115	    const g = settingsAudioCtx.createGain();
1116	    o.type = "sine";
1117	    o.frequency.value = ev === "done" ? 880 : 560;
1118	    g.gain.value = 0.05;
1119	    o.connect(g);
1120	    g.connect(settingsAudioCtx.destination);
1121	    o.start();
1122	    o.stop(settingsAudioCtx.currentTime + 0.13);
1123	  } catch {}
1124	}
