1128	  filePick.type = "file";
1129	  filePick.accept = "audio/*";
1130	  filePick.style.display = "none";
1131	  document.body.appendChild(filePick);
1132	
1133	  const syncNames = () => {
1134	    for (const ev of ["done", "waiting"] as const) {
1135	      const name = localStorage.getItem(`ap_sound_${ev}_name`);
1136	      (document.getElementById(`sound-${ev}-name`) as HTMLElement).textContent = name || t("Default");
1137	      (document.getElementById(`t-df-${ev}`) as HTMLElement).style.display = name ? "" : "none";
1138	    }
1139	  };
1140	  syncNames();
1141	
1142	  document.querySelectorAll<HTMLButtonElement>(".sound-btns .mini").forEach((b) => {
1143	    const ev = b.dataset.ev as "done" | "waiting";
1144	    b.onclick = () => {
1145	      switch (b.dataset.act) {
1146	        case "play": playSound(ev); break;
1147	        case "reset":
1148	          localStorage.removeItem(`ap_sound_${ev}_data`);
1149	          localStorage.removeItem(`ap_sound_${ev}_name`);
1150	          syncNames();
1151	          break;
1152	        case "upload":
1153	          filePick.onchange = () => {
