1159	              localStorage.setItem(`ap_sound_${ev}_data`, String(reader.result));
1160	              localStorage.setItem(`ap_sound_${ev}_name`, f.name);
1161	              syncNames();
1162	              playSound(ev); // preview, like macOS
1163	            };
1164	            reader.readAsDataURL(f);
1165	            filePick.value = "";

