     1	import Foundation
     2	import DesktopPetCore
     3	
     4	/// Maps each pet state to a clip index of an imported sprite pet.
     5	struct PetBindings: Equatable {
     6	    var byMood: [String: Int]
     7	
     8	    func clipIndex(for mood: PetMood) -> Int {
     9	        byMood[mood.rawValue] ?? 0
    10	    }
    11	
    12	    /// Spreads the first clips across states, clamped to what the pack has.
    13	    static func defaults(clipCount: Int) -> PetBindings {
    14	        let order: [PetMood] = [.idle, .working, .waiting, .done, .celebrate, .sleepy, .levelup]
    15	        var map: [String: Int] = [:]
    16	        for (i, mood) in order.enumerated() {
    17	            map[mood.rawValue] = clipCount > 0 ? min(i, clipCount - 1) : 0
    18	        }
    19	        return PetBindings(byMood: map)
    20	    }
    21	}
    22	
    23	/// Persists per-pet state→clip bindings and publishes changes to the UI.
    24	@MainActor
    25	final class PetBindingsStore: ObservableObject {
    26	    static let shared = PetBindingsStore()
    27	
    28	    @Published private var cache: [String: PetBindings] = [:]
    29	
    30	    func bindings(packId: String, clipCount: Int) -> PetBindings {
    31	        if let cached = cache[packId] { return cached }
    32	        let loaded = load(packId) ?? PetBindings.defaults(clipCount: clipCount)
    33	        cache[packId] = loaded
    34	        return loaded
    35	    }
    36	
    37	    func clipIndex(packId: String, clipCount: Int, mood: PetMood) -> Int {
    38	        min(bindings(packId: packId, clipCount: clipCount).clipIndex(for: mood), max(clipCount - 1, 0))
    39	    }
    40	
    41	    func setClip(_ clip: Int, mood: PetMood, packId: String, clipCount: Int) {
    42	        var current = bindings(packId: packId, clipCount: clipCount)
    43	        current.byMood[mood.rawValue] = clip
    44	        cache[packId] = current
    45	        save(packId, current)
    46	    }
    47	
    48	    private func key(_ packId: String) -> String { "desktoppet.bindings.\(packId)" }
    49	
    50	    private func load(_ packId: String) -> PetBindings? {
    51	        guard let data = UserDefaults.standard.data(forKey: key(packId)),
    52	              let map = try? JSONDecoder().decode([String: Int].self, from: data) else { return nil }
    53	        return PetBindings(byMood: map)
    54	    }
    55	
    56	    private func save(_ packId: String, _ bindings: PetBindings) {
    57	        if let data = try? JSONEncoder().encode(bindings.byMood) {
    58	            UserDefaults.standard.set(data, forKey: key(packId))
    59	        }
    60	    }
    61	}

--- SpriteSlicer ---
     1	import AppKit
     2	
     3	/// A pet pack backed by a spritesheet (pet.json + image), e.g. the Codex/petdex
     4	/// pet format. Sliced at load time into clips (one per sheet row); each clip is
     5	/// a separate animation the user can bind to a state.
     6	struct ImagePetPack: Identifiable {
     7	    let id: String
     8	    let displayName: String
     9	    let description: String?
    10	    let clips: [[NSImage]]
    11	    let directory: URL
    12	
    13	    var clipCount: Int { clips.count }
    14	
    15	    func clip(_ index: Int) -> [NSImage] {
    16	        guard !clips.isEmpty else { return [] }
    17	        return clips[min(max(index, 0), clips.count - 1)]
    18	    }
    19	}
    20	
    21	private struct PetManifest: Decodable {
    22	    let id: String
    23	    let displayName: String
    24	    let description: String?
    25	    let spritesheetPath: String
    26	}
    27	
    28	/// Loads a spritesheet pet pack and slices its frames by detecting the
    29	/// transparent gutters between cells, so no grid metadata is required.
    30	enum SpriteSlicer {
    31	    /// Reads only the pack id from a directory's manifest, without slicing the
    32	    /// spritesheet. Lets the store pick the prioritised pack to load first.
    33	    static func manifestID(directory: URL) -> String? {
    34	        let manifestURL = directory.appendingPathComponent("pet.json")
    35	        guard let data = try? Data(contentsOf: manifestURL),
    36	              let manifest = try? JSONDecoder().decode(PetManifest.self, from: data)
    37	        else { return nil }
    38	        return manifest.id
    39	    }
    40	
    41	    static func loadPack(directory: URL) -> ImagePetPack? {
    42	        let manifestURL = directory.appendingPathComponent("pet.json")
    43	        guard let data = try? Data(contentsOf: manifestURL),
    44	              let manifest = try? JSONDecoder().decode(PetManifest.self, from: data)
    45	        else { return nil }
    46	
    47	        let sheetURL = directory.appendingPathComponent(manifest.spritesheetPath)
    48	        guard let nsImage = NSImage(contentsOf: sheetURL) else { return nil }
    49	        var rect = CGRect(origin: .zero, size: nsImage.size)
    50	        guard let cg = nsImage.cgImage(forProposedRect: &rect, context: nil, hints: nil) else { return nil }
    51	
    52	        let clips = slice(cg).map { row in
    53	            row.map { NSImage(cgImage: $0, size: NSSize(width: $0.width, height: $0.height)) }
    54	        }
    55	        guard !clips.isEmpty else { return nil }
    56	        return ImagePetPack(id: manifest.id, displayName: manifest.displayName,
    57	                            description: manifest.description, clips: clips, directory: directory)
    58	    }
    59	
    60	    /// Slices a spritesheet into clips (one per sheet row) using alpha gutter
    61	    /// detection, so no grid metadata is required. Columns are detected within
    62	    /// each row, so ragged sheets (rows with different frame counts or unaligned
    63	    /// columns, e.g. AI-generated sheets) slice correctly. Uniform grids are
    64	    /// unaffected: every row finds the same columns.
    65	    static func slice(_ image: CGImage, alphaThreshold: UInt8 = 16) -> [[CGImage]] {
    66	        let w = image.width, h = image.height
    67	        guard w > 0, h > 0,
    68	              let data = pixelData(image, width: w, height: h) else { return [] }
    69	
    70	        var rowHas = [Bool](repeating: false, count: h)
    71	        data.withUnsafeBufferPointer { buf in
    72	            for y in 0..<h {
    73	                let rowStart = y * w * 4
    74	                for x in 0..<w where buf[rowStart + x * 4 + 3] > alphaThreshold {
    75	                    rowHas[y] = true
    76	                    break
    77	                }
    78	            }
    79	        }
    80	        let rowBands = segments(rowHas)
    81	        guard !rowBands.isEmpty else { return [] }
    82	
    83	        var clips: [[CGImage]] = []
    84	        data.withUnsafeBufferPointer { buf in
    85	            for row in rowBands {
    86	                var colHas = [Bool](repeating: false, count: w)
    87	                for y in row.lower..<row.upper {
    88	                    let rowStart = y * w * 4
    89	                    for x in 0..<w where buf[rowStart + x * 4 + 3] > alphaThreshold {
    90	                        colHas[x] = true
    91	                    }
    92	                }
    93	                var clip: [CGImage] = []
    94	                for col in segments(colHas) {
    95	                    let rect = CGRect(x: col.lower, y: row.lower,
    96	                                      width: col.upper - col.lower, height: row.upper - row.lower)
    97	                    guard let cropped = image.cropping(to: rect) else { continue }
    98	                    let fw = Int(rect.width), fh = Int(rect.height)
    99	                    let space = CGColorSpaceCreateDeviceRGB()
   100	                    let info = CGImageAlphaInfo.premultipliedLast.rawValue
   101	                    guard let ctx = CGContext(data: nil, width: fw, height: fh,
   102	                                             bitsPerComponent: 8, bytesPerRow: fw * 4,
   103	                                             space: space, bitmapInfo: info) else { continue }
   104	                    ctx.draw(cropped, in: CGRect(origin: .zero, size: CGSize(width: fw, height: fh)))
   105	                    guard let frame = ctx.makeImage() else { continue }
   106	                    clip.append(frame)
   107	                }
   108	                if !clip.isEmpty { clips.append(clip) }
   109	            }
   110	        }
   111	        return clips
   112	    }
   113	
   114	    private static func pixelData(_ image: CGImage, width: Int, height: Int) -> [UInt8]? {
   115	        var data = [UInt8](repeating: 0, count: width * height * 4)
   116	        let space = CGColorSpaceCreateDeviceRGB()
   117	        let info = CGImageAlphaInfo.premultipliedLast.rawValue
   118	        guard let ctx = data.withUnsafeMutableBytes({ ptr -> CGContext? in
   119	            CGContext(data: ptr.baseAddress, width: width, height: height,
   120	                      bitsPerComponent: 8, bytesPerRow: width * 4,
   121	                      space: space, bitmapInfo: info)
   122	        }) else { return nil }
   123	        ctx.draw(image, in: CGRect(x: 0, y: 0, width: width, height: height))
   124	        return data
   125	    }
   126	
   127	    private static func segments(_ occupancy: [Bool]) -> [(lower: Int, upper: Int)] {
   128	        var result: [(Int, Int)] = []
   129	        var start: Int?
   130	        for (i, filled) in occupancy.enumerated() {
   131	            if filled, start == nil { start = i }
   132	            else if !filled, let s = start { result.append((s, i)); start = nil }
   133	        }
   134	        if let s = start { result.append((s, occupancy.count)) }
   135	        return result
   136	    }
   137	}

