 1	// Renders + animates a pet spritesheet on a canvas. Sheets are sliced with
 2	// alpha-gutter detection (a port of the macOS app's SpriteSlicer): transparent
 3	// gaps split the sheet into rows, then each row into frames. That way empty
 4	// cells in a row simply don't exist , the pet never blinks out on sparse rows,
 5	// and ragged/AI-generated sheets slice correctly. Falls back to a fixed 8x9
 6	// grid when pixels can't be read (no CORS).
 7	
 8	const COLS = 8;
 9	const ROWS = 9;
10	const ALPHA_THRESHOLD = 16;
11	
12	// Row index per state, matching the macOS app's spritesheet layout:
13	// 0 Idle, 1 RunRight, 2 RunLeft, 3 Waving, 4 Jumping, 5 Failed, 6 Waiting, 7 Running, 8 Review
14	const STATE_ROW: Record<string, number> = {
15	  idle: 0,
16	  registered: 0,
17	  working: 7,
18	  waiting: 6,
19	  done: 3,       // waving goodbye to the finished task
20	  celebrate: 4,  // jumping , the 3s burst when all work completes
21	};
