58	    const n = Number.parseFloat(localStorage.getItem(IDLE_INTERVAL_KEY) ?? "");
59	    if (Number.isFinite(n) && n >= 1) return Math.round(n * 1000);
60	  } catch {}
61	  return DEFAULT_IDLE_INTERVAL_S * 1000;
62	}
63	
64	/// Contiguous runs of `true` in an occupancy array → [start, end) pairs.
65	function segments(occ: Uint8Array): Array<[number, number]> {
66	  const out: Array<[number, number]> = [];
67	  let start = -1;
68	  for (let i = 0; i < occ.length; i++) {
69	    if (occ[i] && start < 0) start = i;
70	    else if (!occ[i] && start >= 0) { out.push([start, i]); start = -1; }
71	  }
72	  if (start >= 0) out.push([start, occ.length]);

